  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 2000);
});

test('removeLine preserves voucher when modifying draft', () => {
  const draft = createInvoice({
    customerId: 'C-001',
