});

test('addLine preserves voucher when modifying draft', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 2000 });
