});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 5, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 500 + 250);
  const vat1 = (5000 - 500) * 0.21;
  const vat2 = (5000 - 250) * 0.09;
  assert.equal(totals.vat, Math.round(vat1) + Math.round(vat2));
  assert.equal(totals.total, 10000 - 750 + Math.round(vat1) + Math.round(vat2));
});

