test('invoiceTotals with tier discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 5, vatRate: 0 },
      { qty: 3, unitPrice: 500, discountPercent: 2.5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000 + 1500);
  assert.equal(totals.discount, 250 + 37);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 6500 - 287);
});

test('lineVAT calculates VAT on line amount after discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const vat = lineVAT(line);
  const lineAmountAfterDiscount = 5000 - 500;
  const expectedVat = lineAmountAfterDiscount * 0.21;
  assert.equal(vat, Math.round(expectedVat));
});

test('lineVAT with 0% VAT rate', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const vat = lineVAT(line);
  assert.equal(vat, 0);
});

test('lineVAT with 9% VAT rate', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 9 };
  const vat = lineVAT(line);
  assert.equal(vat, 450);
});

test('lineVAT with 21% VAT rate', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 1050);
});

test('lineVAT rounds per line', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  const amountAfterDiscount = 300;
  const calculatedVat = amountAfterDiscount * 0.21;
  assert.equal(calculatedVat, 63);
  assert.equal(vat, 63);
});

test('lineVAT with fractional result rounds correctly', () => {
  const line = { qty: 1, unitPrice: 333, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 70);
});

test('lineVAT with discount reduces VAT base', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 50, vatRate: 21 };
  const vat = lineVAT(line);
  const amountAfterDiscount = 5000 - 2500;
  const expectedVat = amountAfterDiscount * 0.21;
  assert.equal(vat, Math.round(expectedVat));
  assert.equal(vat, 525);
});

test('invoiceTotals returns vat field', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 1050);
});

test('invoiceTotals calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 500);
  const expectedVat = (5000 - 500) * 0.21;
  assert.equal(totals.vat, Math.round(expectedVat));
  assert.equal(totals.total, 5000 - 500 + Math.round(expectedVat));
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1050 + 450);
  assert.equal(totals.total, 15000 + 1500);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 5, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 500 + 250);
  const vat1 = (5000 - 500) * 0.21;
  const vat2 = (5000 - 250) * 0.09;
  assert.equal(totals.vat, Math.round(vat1) + Math.round(vat2));
  assert.equal(totals.total, 10000 - 750 + Math.round(vat1) + Math.round(vat2));
});

test('invoiceTotals with no discount, no VAT', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 5000);
});

test('invoiceTotals clamps total to 0 if discount > subtotal', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals VAT is sum of rounded line VATs', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Vat = lineVAT(invoice.lines[0]);
  const line2Vat = lineVAT(invoice.lines[1]);
  const line3Vat = lineVAT(invoice.lines[2]);
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
  assert.equal(totals.vat, 63);
});

