test('applyVoucher adds a fixed discount to a draft invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 5000);
});

test('applyVoucher returns NOT_DRAFT for non-draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const r = applyVoucher(issued.value, { code: 'SUMMER2026', amount: 1000 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher returns VOUCHER_EXISTS if voucher already applied', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 1000 });
  const r = applyVoucher(withVoucher.value, { code: 'ANOTHER', amount: 500 });
  assert.deepEqual(r, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher returns AMOUNT_INVALID for non-positive amounts', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const testCases = [0, -100, 1.5, 'notanumber', undefined, null];
  for (const amount of testCases) {
    const r = applyVoucher(draft.value, { code: 'TEST', amount });
    assert.equal(r.ok, false, `should reject amount: ${amount}`);
    assert.equal(r.error, 'AMOUNT_INVALID', `should reject amount: ${amount}`);
  }
});

test('invoiceTotals includes voucher in calculation', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const totalsWithoutVoucher = invoiceTotals(draft.value);
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 5000 });
  const totalsWithVoucher = invoiceTotals(withVoucher.value);
  assert.equal(totalsWithVoucher.voucher, 5000);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 5000);
});

test('addLine preserves voucher when modifying draft', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 2000 });
  const r = addLine(withVoucher.value, { sku: 'STICKER', qty: 10 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 2000);
});

test('removeLine preserves voucher when modifying draft', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'STICKER', qty: 10 },
    ],
  });
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 2000 });
  const r = removeLine(withVoucher.value, 'STICKER');
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 2000);
});

test('issueInvoice preserves voucher', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const withVoucher = applyVoucher(draft.value, { code: 'SUMMER2026', amount: 2000 });
  const r = issueInvoice(withVoucher.value, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'SUMMER2026');
  assert.equal(r.value.voucher.amount, 2000);
});

test('invoiceTotals returns voucher amount as 0 when no voucher', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const totals = invoiceTotals(draft.value);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

