test('lineVAT calculates VAT on line amount after discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const vat = lineVAT(line);
  const lineAmountAfterDiscount = 5000 - 500;
  const expectedVat = lineAmountAfterDiscount * 0.21;
  assert.equal(vat, Math.round(expectedVat));
});

