test('invoiceTotals calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 500);
  const expectedVat = (5000 - 500) * 0.21;
  assert.equal(totals.vat, Math.round(expectedVat));
  assert.equal(totals.total, 5000 - 500 + Math.round(expectedVat));
});

